import { type NextRequest, NextResponse } from "next/server";
import { MVR_ENDPOINTS } from "@/lib/endpoints";

export const runtime = "edge";
// 1 hour
export const revalidate = 60 * 60;

// The sitemap (packages, org pages and static pages) is generated by the API.
const API_XML_URL = `${MVR_ENDPOINTS.mainnet}/v1/sitemap`;

const API_TIMEOUT_MS = 10_000;

export async function GET(_: NextRequest) {
  // `null` on a network error / timeout.
  const response = await fetch(API_XML_URL, {
    signal: AbortSignal.timeout(API_TIMEOUT_MS),
  }).catch(() => null);

  // Do not serve (and let crawlers / CDNs cache) an upstream error as a sitemap.
  if (!response?.ok) {
    return new NextResponse("Sitemap is temporarily unavailable", {
      status: 502,
      headers: { "Cache-Control": "no-store" },
    });
  }

  const xml = await response.text();

  return new NextResponse(xml, {
    status: 200,
    headers: {
      "Content-Type": "application/xml",
      "Cache-Control":
        "public, max-age=3600, s-maxage=3600, stale-while-revalidate=60",
    },
  });
}
